/**
 * The types `data/vault/` exports, in one place — so a neighbouring module finds the shape it
 * needs here instead of declaring its own under a second name.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    VaultTreeChildSort, VaultTreeNode, VaultTreeKey, VaultTreeDefinition
 * depends    —
 * used by    src/data/vault/index, src/data/vault/tree, src/data/vault/tree-traversal, src/save/catalogs/vault/power-mapping, src/save/catalogs/vault/slot-bindings
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */

// from tree-traversal.ts

export type VaultTreeChildSort = 'col-row' | 'row-col'

// from tree.ts

export interface VaultTreeNode {
  id: string
  name: string
  cost: number | number[]
  col: number
  row: number
  parents: string[]
}

export type VaultTreeKey = 'power' | 'harmony'

export interface VaultTreeDefinition {
  key: VaultTreeKey
  label: string
  description: string
  nodes: readonly VaultTreeNode[]
  nodeCount: number
  rootNodeIds: readonly string[]
  rootNodeLabels: readonly string[]
  totalKeyCost: number
  minimumNodeCost: number
  maximumNodeCost: number
}
